-- MANUAL_SQL: Source supabase/schemas/34_scheduled_jobs.sql
-- =============================================================================
-- 34_scheduled_jobs.sql — Durable pg_cron scheduling
-- =============================================================================
-- These rows are operational state rather than schema objects. Keep this file
-- as the source of truth and copy both idempotent blocks into fresh baselines,
-- because `supabase db diff` does not emit DML-managed cron jobs.

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM cron.job
    WHERE jobname = 'cleanup-expired-app-tutorial-runs'
  ) THEN
    PERFORM cron.schedule(
      'cleanup-expired-app-tutorial-runs',
      '17 3 * * *',
      'SELECT public.cleanup_expired_app_tutorial_runs();'
    );
  END IF;
END
$$;

DO $$
DECLARE
  existing_job_id BIGINT;
BEGIN
  IF to_regclass('vault.decrypted_secrets') IS NULL THEN
    RETURN;
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM vault.decrypted_secrets
    WHERE name = 'push_delivery_secret'
  ) THEN
    RETURN;
  END IF;

  SELECT jobid
  INTO existing_job_id
  FROM cron.job
  WHERE jobname = 'push-delivery-sync';

  IF existing_job_id IS NOT NULL THEN
    PERFORM cron.unschedule(existing_job_id);
  END IF;

  PERFORM cron.schedule(
    'push-delivery-sync',
    '* * * * *',
    $cron$
      SELECT net.http_post(
        url := 'https://www.polity.live/api/push/process',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || (
            SELECT decrypted_secret
            FROM vault.decrypted_secrets
            WHERE name = 'push_delivery_secret'
          )
        ),
        body := '{"source":"scheduler"}'::jsonb
      );
    $cron$
  );
END
$$;


-- MANUAL_SQL: Source supabase/schemas/98_publications.sql
-- MANUAL_SQL: migra does not track publication membership.
-- Zero normally owns its publications. Extend only an existing legacy `zero`
-- publication with an explicit table list; do not create or alter runtime ones.
DO $$
DECLARE table_name TEXT;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'zero' AND NOT puballtables) THEN
    FOREACH table_name IN ARRAY ARRAY[
      'studio_state', 'canvas_proposal', 'canvas_workspace_reader',
      'studio_command_receipt', 'studio_asset', 'studio_revision',
      'canvas_control', 'canvas_vote', 'canvas_comment', 'canvas_history',
      'canvas_library', 'canvas_role_capability', 'canvas_receipt',
      'studio_editor_action', 'studio_element_set', 'studio_element_set_revision',
      'studio_live_source', 'event_presentation', 'event_presentation_device'
    ] LOOP
      IF NOT EXISTS (
        SELECT 1 FROM pg_publication_tables
        WHERE pubname = 'zero' AND schemaname = 'public' AND tablename = table_name
      ) THEN
        EXECUTE format('ALTER PUBLICATION zero ADD TABLE public.%I', table_name);
      END IF;
    END LOOP;
  END IF;
END
$$;


